CREATE TYPE "userek_nem" AS ENUM ('ferfi','no','egyeb');
CREATE TYPE "userek_cel" AS ENUM ('izomtomeg_noveles','fogyas','erodobas','szintentartas');
CREATE TYPE "userek_rang" AS ENUM ('tag','edzo','admin');
CREATE TYPE "kaja_kategoria" AS ENUM ('hus','hal_tengeri','tejtermek_tojas','zoldseg','gyumolcs','gabonafele_teszta','huvelyes','magvas_zsir');
CREATE TYPE "WorkoutStatus" AS ENUM ('in_progress','completed','cancelled');
CREATE TYPE "PlanShareStatus" AS ENUM ('pending','accepted','declined','revoked','expired');
CREATE TYPE "NotificationType" AS ENUM ('plan_share_received','plan_share_accepted');
CREATE TABLE "userek" ("id" SERIAL PRIMARY KEY,"nev" VARCHAR(100) NOT NULL,"username" VARCHAR(40) UNIQUE,"username_normalized" VARCHAR(40) UNIQUE,"bio" VARCHAR(500),"avatar_url" VARCHAR(2048),"profil_publikus" BOOLEAN NOT NULL DEFAULT true,"email" VARCHAR(150) NOT NULL UNIQUE,"jelszo_hash" VARCHAR(255) NOT NULL,"suly_kg" DECIMAL(5,2),"magassag_cm" INTEGER,"eletkor" INTEGER,"nem" "userek_nem","cel" "userek_cel" DEFAULT 'izomtomeg_noveles',"rang" "userek_rang" DEFAULT 'tag',"letrehozva" TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "izomcsoportok" ("id" SERIAL PRIMARY KEY,"nev" VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE "gyakorlatok" ("id" SERIAL PRIMARY KEY,"nev" VARCHAR(100) NOT NULL,"elsodleges_izomcsoport_id" INTEGER NOT NULL REFERENCES "izomcsoportok"("id") ON DELETE CASCADE,"masodlagos_izomcsoport_id" INTEGER REFERENCES "izomcsoportok"("id") ON DELETE SET NULL);
CREATE TABLE "edzestervek" ("id" SERIAL PRIMARY KEY,"user_id" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"nev" VARCHAR(100) NOT NULL,"leiras" TEXT,"aktiv" BOOLEAN DEFAULT true,"publikus" BOOLEAN DEFAULT false,"letrehozva" TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "edzes_napok" ("id" SERIAL PRIMARY KEY,"edzesterv_id" INTEGER NOT NULL REFERENCES "edzestervek"("id") ON DELETE CASCADE,"nev" VARCHAR(100) NOT NULL,"sorrend" INTEGER NOT NULL DEFAULT 1, UNIQUE("edzesterv_id","sorrend"));
CREATE TABLE "edzesterv_gyakorlatok" ("id" SERIAL PRIMARY KEY,"edzes_nap_id" INTEGER NOT NULL REFERENCES "edzes_napok"("id") ON DELETE CASCADE,"gyakorlat_id" INTEGER NOT NULL REFERENCES "gyakorlatok"("id") ON DELETE CASCADE,"sorrend" INTEGER NOT NULL DEFAULT 1,"sorozatszam" INTEGER DEFAULT 3,"ismetlesszam_min" INTEGER DEFAULT 8,"ismetlesszam_max" INTEGER DEFAULT 12,"piheno_masodperc" INTEGER DEFAULT 90,"megjegyzese" TEXT, UNIQUE("edzes_nap_id","sorrend"));
CREATE TABLE "kaja" ("id" SERIAL PRIMARY KEY,"nev" VARCHAR(100) NOT NULL UNIQUE,"kategoria" "kaja_kategoria" NOT NULL,"kaloria" DECIMAL(6,2) NOT NULL,"feherje" DECIMAL(5,2) NOT NULL,"szenhidrat" DECIMAL(5,2) NOT NULL,"zsir" DECIMAL(5,2) NOT NULL);
CREATE TABLE "AuthSession" ("id" TEXT PRIMARY KEY,"userId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"refreshHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WorkoutSession" ("id" SERIAL PRIMARY KEY,"userId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"sourcePlanId" INTEGER REFERENCES "edzestervek"("id") ON DELETE SET NULL,"sourceDayId" INTEGER REFERENCES "edzes_napok"("id") ON DELETE SET NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"finishedAt" TIMESTAMP(3),"status" "WorkoutStatus" NOT NULL DEFAULT 'in_progress',"note" TEXT);
CREATE TABLE "SessionExercise" ("id" SERIAL PRIMARY KEY,"sessionId" INTEGER NOT NULL REFERENCES "WorkoutSession"("id") ON DELETE CASCADE,"exerciseId" INTEGER REFERENCES "gyakorlatok"("id") ON DELETE SET NULL,"exerciseName" VARCHAR(100) NOT NULL,"sorrend" INTEGER NOT NULL,"note" TEXT, UNIQUE("sessionId","sorrend"));
CREATE TABLE "WorkoutSet" ("id" SERIAL PRIMARY KEY,"sessionExerciseId" INTEGER NOT NULL REFERENCES "SessionExercise"("id") ON DELETE CASCADE,"sorrend" INTEGER NOT NULL,"weight" DECIMAL(7,2),"repetitions" INTEGER NOT NULL,"rpe" DECIMAL(3,1),"completed" BOOLEAN NOT NULL DEFAULT false,"completedAt" TIMESTAMP(3), UNIQUE("sessionExerciseId","sorrend"));
CREATE TABLE "PlanShare" ("id" SERIAL PRIMARY KEY,"sourcePlanId" INTEGER NOT NULL REFERENCES "edzestervek"("id") ON DELETE CASCADE,"senderId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"recipientId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"message" VARCHAR(500),"status" "PlanShareStatus" NOT NULL DEFAULT 'pending',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"respondedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3) NOT NULL,"copiedPlanId" INTEGER UNIQUE REFERENCES "edzestervek"("id") ON DELETE SET NULL, UNIQUE("sourcePlanId","recipientId","status"));
CREATE TABLE "Notification" ("id" SERIAL PRIMARY KEY,"recipientId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"type" "NotificationType" NOT NULL,"resourceId" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"readAt" TIMESTAMP(3));
CREATE TABLE "UserBlock" ("blockerId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"blockedId" INTEGER NOT NULL REFERENCES "userek"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY("blockerId","blockedId"));
CREATE INDEX "gyakorlatok_primary_idx" ON "gyakorlatok"("elsodleges_izomcsoport_id"); CREATE INDEX "edzestervek_user_idx" ON "edzestervek"("user_id"); CREATE INDEX "AuthSession_user_expiry_idx" ON "AuthSession"("userId","expiresAt"); CREATE INDEX "WorkoutSession_active_idx" ON "WorkoutSession"("userId","status","startedAt"); CREATE UNIQUE INDEX "WorkoutSession_one_active" ON "WorkoutSession"("userId") WHERE "status" = 'in_progress'; CREATE INDEX "PlanShare_recipient_idx" ON "PlanShare"("recipientId","status","createdAt"); CREATE INDEX "PlanShare_sender_idx" ON "PlanShare"("senderId","status","createdAt"); CREATE INDEX "Notification_recipient_idx" ON "Notification"("recipientId","readAt","createdAt"); CREATE INDEX "UserBlock_blocked_idx" ON "UserBlock"("blockedId");
